export async function runCapturePool({browser,serve,evidence,root}){
  const server=await serve(root),context=await browser.newContext(),page=await context.newPage(),ordinaryOnly=process.env.SCOREBRUSH_POOL_ORDINARY_ONLY==='1';let details={cases:[],scope:ordinaryOnly?'ordinary-foundation-only':'publication-and-recovery-pool'},carry;
  await page.route('**/synthetic-capture-pool',route=>route.fulfill({contentType:'text/html',body:'<!doctype html><title>SYNTHETIC inactive capture pool</title>'}));
  try{
    await page.goto(server.origin+'/synthetic-capture-pool');
    for(const phase of (ordinaryOnly?['ordinary','restart','refusals']:['ordinary','restart','refusals','archives','repairs','bounded'])){
      if(phase!=='ordinary')await page.reload();
      const result=await page.evaluate(poolPage,{phase,carry});carry=result.carry??carry;details.cases.push(...result.cases);if(result.measurements)details.measurements=result.measurements;
    }
    for(const item of details.cases){assert(item.pass,item.name);console.log('capture-pool: '+item.name);}
    return {name:'capture-pool',assertions:details.cases.length,cases:details.cases.length,realIndexedDB:true,realOPFS:true,scope:details.scope};
  }catch(error){details.failure={name:error.name,message:error.message,stack:error.stack};const latest=await page.evaluate(()=>window.capturePoolCases??[]).catch(()=>[]);if(latest.length)details.interruptedCases=latest;details.failedMeasurements=await page.evaluate(()=>window.capturePoolMeasurements??[]).catch(()=>[]);throw error;}
  finally{await writeFile(resolve(evidence,'capture-pool.json'),JSON.stringify(details,null,2)+'\n');await writeFile(resolve(evidence,'capture-pool.txt'),[...details.cases.map(item=>(item.pass?'PASS ':'FAIL ')+item.name),...(details.failure?['FAIL '+details.failure.message]:[])].join('\n')+'\n');await context.close();await server.close();}
}

